-- Liquid-glass look. Colors come from colors.lua (generated by matugen via scripts/wallpaper.sh).
local C = COLORS

hl.config({
    general = {
        gaps_in     = 6,
        gaps_out    = 12,
        border_size = 2,
        col = {
            active_border   = { colors = { C.primary_a, C.tertiary_a }, angle = 45 },
            inactive_border = C.outline_dim,
        },
        layout = "dwindle",
    },

    decoration = {
        rounding           = 14,
        active_opacity     = 0.90,
        inactive_opacity   = 0.80,
        fullscreen_opacity = 1.0,

        blur = {
            enabled    = true,
            size       = 8,
            passes     = 3,
            noise      = 0.02,
            brightness = 0.9,
            vibrancy   = 0.2,
            popups     = true,
        },

        shadow = {
            enabled      = true,
            range        = 25,
            render_power = 3,
            color        = C.shadow_a,
        },
    },

    animations = {
        enabled = true,
    },
})

hl.curve("glass",   { type = "bezier", points = { { 0.22, 1 },   { 0.36, 1 } } })
hl.curve("overshot", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.1 } } })
hl.curve("linear",  { type = "bezier", points = { { 0, 0 },      { 1, 1 } } })

hl.animation({ leaf = "windows",     enabled = true, speed = 5, bezier = "overshot", style = "popin 80%" })
hl.animation({ leaf = "windowsOut",  enabled = true, speed = 4, bezier = "glass",    style = "popin 80%" })
hl.animation({ leaf = "border",      enabled = true, speed = 8, bezier = "glass" })
-- no `loop`: a forever-spinning border redraws (and re-blurs) the whole screen at 60 fps, which left the UHD 620
-- no headroom for workspace switches
hl.animation({ leaf = "borderangle", enabled = true, speed = 8, bezier = "glass" })
hl.animation({ leaf = "fade",        enabled = true, speed = 4, bezier = "glass" })
hl.animation({ leaf = "layers",      enabled = true, speed = 4, bezier = "glass", style = "slide" })
-- 300 ms: the glass stack renders at ~30 fps during a switch on this throttled UHD 620, so keep it short
hl.animation({ leaf = "workspaces",  enabled = true, speed = 3, bezier = "glass", style = "slidefade 15%" })

-- Stay fully opaque: browsers, media, games, image viewers
hl.window_rule({ name = "opaque-apps", match = { class = "^(firefox|google-chrome|Google-chrome|chromium|brave-browser|mpv|vlc|imv|org.gnome.Loupe|org.kde.gwenview|org.vinegarhq.Sober|steam)$" }, opaque = true })
-- Chrome web apps (Wayland: chrome-<id>-Default, X11: crx_<id>)
hl.window_rule({ name = "opaque-webapps", match = { class = "^(chrome-.*|crx_.*)$" }, opaque = true })
hl.window_rule({ name = "opaque-games", match = { class = "^(steam_app_.*)$" }, opaque = true })
hl.window_rule({ name = "opaque-video", match = { content = 2 }, opaque = true })
hl.window_rule({ name = "opaque-game-content", match = { content = 3 }, opaque = true })
-- Kitty handles its own transparency (background_opacity in kitty.conf) so text stays crisp
hl.window_rule({ name = "opaque-kitty", match = { class = "^(kitty)$" }, opaque = true })

-- Blur behind bar, launcher and notifications
hl.layer_rule({ name = "blur-panels", match = { namespace = "^(waybar|rofi|notifications|logout_dialog)$" }, blur = true })
hl.layer_rule({ name = "alpha-panels", match = { namespace = "^(waybar|rofi|notifications)$" }, ignore_alpha = 0.3 })
-- Kitty drop-down terminal (kitten quick-access-terminal)
hl.layer_rule({ name = "blur-quick-terminal", match = { namespace = "^(kitty-quick-access)$" }, blur = true })

-- MacShell (quickshell): HyprGlass (plugins.lua) draws all its glass, so no Hyprland blur here: it would be
-- drawn into the layer on top of the glass (and from a stale cached wallpaper blur). No fade on the screenshot picker.
hl.layer_rule({ name = "macshell-no-anim", match = { namespace = "^(macdock|macspot|macbarbg|macshot|macswitch)$" }, no_anim = true })
